import { downloadBlob } from '@/utils/stream-download';
import { render, h as vueH } from 'vue';
import ImageDownloadButton from './ImageDownloadButton.vue';
import ImageInfoDisplay from './ImageInfoDisplay.vue';
import ImageIndexBadge from './ImageIndexBadge.vue';
import { detectFormat, embedMetadataInPng, embedMetadataInWebp, UNSUPPORTED } from '@/utils/image-metadata';
import { sanitizeFilename } from '@/utils/string';
import type { StorageService } from '@/00-storage/service';
import { toBinaryObjectId } from '@/01-models/ids';
import type { BinaryObjectId } from '@/01-models/ids';
import { twClassString } from 'virtual:naidan-tailwind';

/**
 * ImageDownloadHydrator handles the manual attachment of the Vue-based
 * download button and image elements to a DOM element within a v-html block.
 */
export const ImageDownloadHydrator = {
  /**
   * Extract all necessary data from the placeholder element to prepare for hydration.
   * If a blob is already available, it can be passed to avoid redundant storage reads.
   */
  async prepareContext({ el, storageService, blob }: { el: HTMLElement, storageService: StorageService, blob?: Blob }) {
    const id = el.dataset.id;
    if (!id) return null;

    // Detect format for metadata support
    let isSupported = false;
    try {
      const activeBlob = blob || await storageService.getFile({ binaryObjectId: toBinaryObjectId({ raw: id }) });
      if (activeBlob) {
        isSupported = await this.detectSupport({ blob: activeBlob });
      }
    } catch (err) {
      console.warn('[Hydrator] Metadata support detection failed:', err);
    }

    return {
      id,
      isSupported,
      width: el.dataset.width,
      height: el.dataset.height,
      prompt: el.dataset.prompt || '',
      steps: el.dataset.steps ? parseInt(el.dataset.steps) : undefined,
      seed: el.dataset.seed ? parseInt(el.dataset.seed) : undefined,
    };
  },

  /**
   * Detects if the given blob's format supports metadata embedding.
   */
  async detectSupport({ blob }: { blob: Blob }): Promise<boolean> {
    try {
      const format = await detectFormat({ blob });
      return format !== UNSUPPORTED;
    } catch (err) {
      console.warn('[Hydrator] Format detection failed:', err);
      return false;
    }
  },

  /**
   * Creates a standard image element for generated images with the correct styling and behavior.
   */
  createImageElement({ url, width, height, onPreview }: {
    url: string,
    width: string | undefined,
    height: string | undefined,
    onPreview: () => void,
  }): HTMLImageElement {
    const imgEl = document.createElement('img');
    imgEl.src = url;
    imgEl.width = parseInt(width || '512');
    imgEl.height = parseInt(height || '512');
    // TODO(strings-localize): Localize this DOM attribute after createImageElement can receive a resolved alt value without becoming asynchronous.
    imgEl.alt = 'generated image';
    imgEl.className = [
      'naidan-clickable-img',
      twClassString(
        'rounded-xl', 'shadow-lg', 'border', 'border-gray-100', 'dark:border-gray-800',
        'max-w-full', 'h-auto', '!m-0', 'block', 'cursor-pointer', 'hover:opacity-95',
        'transition-opacity',
      ),
    ].join(' ');
    imgEl.onclick = (e) => {
      e.stopPropagation();
      onPreview();
    };
    return imgEl;
  },

  /**
   * Orchestrates the download of a generated image, optionally embedding metadata.
   */
  async download({ id, name, memoryBlob, prompt, steps, seed, model, withMetadata, storageService, onError }: {
    id: BinaryObjectId,
    name: string | undefined,
    memoryBlob: Blob | undefined,
    prompt: string,
    steps: number | undefined,
    seed: number | undefined,
    model: string | undefined,
    withMetadata: boolean,
    storageService: StorageService,
    onError: ({ error }: { error: unknown }) => void,
  }) {
    try {
      const obj = memoryBlob === undefined ? await storageService.getBinaryObject({ binaryObjectId: id }) : undefined;
      const blob = memoryBlob ?? await storageService.getFile({ binaryObjectId: id });
      if (!blob) throw new Error('Image blob not found');

      let suffix = '.png';
      const filenameHint = name ?? obj?.name;
      if (filenameHint) {
        const lastDot = filenameHint.lastIndexOf('.');
        if (lastDot !== -1) suffix = filenameHint.slice(lastDot);
      }

      let finalBlob = blob;
      if (withMetadata) {
        try {
          const metadata = { prompt, steps, seed, model };
          if (suffix.toLowerCase() === '.png') {
            finalBlob = await embedMetadataInPng({ blob, metadata });
          } else if (suffix.toLowerCase() === '.webp') {
            finalBlob = await embedMetadataInWebp({ blob, metadata });
          }
        } catch (err) {
          console.error('[Hydrator] Failed to embed metadata:', err);
          onError({ error: err });
        }
      }

      const filename = sanitizeFilename({
        base: prompt,
        suffix,
        fallback: 'generated-image',
      });

      downloadBlob({ blob: finalBlob, filename });
    } catch (err) {
      console.error('[Hydrator] Failed to download generated image:', err);
    }
  },

  /**
   * Mounts the download button into the portal.
   * Returns a cleanup function.
   */
  mount({ portal, isSupported, align, onDownload }: {
    portal: HTMLElement,
    isSupported: boolean,
    align?: 'left' | 'right',
    onDownload: ({ withMetadata }: { withMetadata: boolean }) => void,
  }): () => void {
    const vnode = vueH(ImageDownloadButton, {
      isSupported,
      align,
      onDownload,
    });

    render(vnode, portal);

    return () => {
      render(null, portal);
    };
  },

  /**
   * Mounts the info display into the portal.
   * Returns a cleanup function.
   */
  mountInfo({ portal, prompt, steps, seed, width, height, align }: {
    portal: HTMLElement,
    prompt: string,
    steps: number | undefined,
    seed: number | undefined,
    width: number | string | undefined,
    height: number | string | undefined,
    align?: 'left' | 'right',
  }): () => void {
    const vnode = vueH(ImageInfoDisplay, {
      prompt,
      steps,
      seed,
      width,
      height,
      align,
    });

    render(vnode, portal);

    return () => {
      render(null, portal);
    };
  },

  /**
   * Mounts the index badge into the portal.
   * Returns a cleanup function.
   */
  mountBadge({ portal, index, total }: {
    portal: HTMLElement,
    index: number,
    total?: number,
  }): () => void {
    const vnode = vueH(ImageIndexBadge, {
      index,
      total,
    });

    render(vnode, portal);

    return () => {
      render(null, portal);
    };
  },
};

