<script setup lang="ts">
import { lazyStrings } from '@/strings';
import { ref, computed } from 'vue';
import { ImageIcon, EyeIcon, GlobeIcon } from 'lucide-vue-next';
import { useExternalResourceSettings } from '@/composables/useExternalResourceSettings';

const props = defineProps<{
  src: string,
  alt: string | undefined,
  title: string | undefined,
}>();

const { allowAllExternalImages, setAllowAllExternalImages } = useExternalResourceSettings();
const showThisImage = ref(false);

const isExternal = computed(() => {
  try {
    // Relative URLs or data URLs are not "external" in the sense of leaking IP to 3rd party
    if (props.src.startsWith('data:') || props.src.startsWith('blob:') || props.src.startsWith('./') || props.src.startsWith('/') || !props.src.includes('://')) {
      return false;
    }
    const url = new URL(props.src);
    return url.origin !== window.location.origin;
  } catch (e) {
    // Fail safe: if URL is invalid or parsing fails, treat as external/untrusted
    return true;
  }
});

const shouldShow = computed(() => !isExternal.value || allowAllExternalImages.value || showThisImage.value);

function load() {
  showThisImage.value = true;
}

function loadAll() {
  setAllowAllExternalImages({ allow: true });
}

defineExpose({
  ...((__BUILD_MODE_IS_TEST__ && {
    TEST_ONLY: {
      showThisImage,
      isExternal,
      shouldShow,
    },
  }) || {}),
});

import "virtual:naidan-tailwind-css-module/e40bc904c786b5e9b6d5d61d2c4dd934a3c92e31e2662ea2701aeab4186f30e5.js";
import "virtual:naidan-tailwind-css-module/ebecc4fd674ef82f183437255486fe38e6831e60d5730478c48be6aabd6a8f8f.js";
</script>

<template>
  <span v-if="!shouldShow" class="naidan-external-image-placeholder" tw-class="inline-flex items-center gap-1 px-1 py-0.5 my-1 bg-gray-100 dark:bg-gray-800 border border-gray-200 dark:border-gray-700 rounded text-xs text-gray-600 dark:text-gray-400 align-middle select-none">
    <span tw-class="flex items-center gap-1.5 px-2 py-0.5 hover:bg-gray-200 dark:hover:bg-gray-700 cursor-pointer rounded transition-colors" @click="load" :title="src">
      <ImageIcon tw-class="w-3.5 h-3.5" />
      <span tw-class="max-w-[150px] truncate font-medium">{{ alt || lazyStrings.blockMarkdown__external_image() }}</span>
      <EyeIcon tw-class="w-3.5 h-3.5 opacity-70" />
    </span>
    <span tw-class="w-[1px] h-3 bg-gray-300 dark:bg-gray-600 mx-0.5"></span>
    <button tw-class="p-1 hover:bg-gray-200 dark:hover:bg-gray-700 rounded transition-colors" @click="loadAll" :title="lazyStrings.blockMarkdown__allow_all_external_images_in_this_session()">
      <GlobeIcon tw-class="w-3.5 h-3.5" />
    </button>
  </span>
  <img
    v-else
    :src="src"
    :alt="alt"
    :title="title"
    tw-class="max-w-full h-auto rounded-lg shadow-sm my-2 inline-block align-middle"
  />
</template>
