<script setup lang="ts">
import { lazyStrings } from '@/strings';
import { ref } from 'vue';
import { DownloadIcon, ChevronDownIcon } from 'lucide-vue-next';
import { useEventTargetListener } from '@/composables/useEventTargetListener';

const props = defineProps<{
  /** Download action handler */
  onDownload: ({ withMetadata }: { withMetadata: boolean }) => void,
  /** Whether metadata embedding is supported for the current image format */
  isSupported?: boolean,
  /** Alignment of the dropdown: 'left' or 'right' (default) */
  align?: 'left' | 'right',
}>();

const isOpen = ref(false);
const dropdownRef = ref<HTMLElement | null>(null);

function toggleDropdown({ event }: { event: Event }) {
  event.stopPropagation();
  isOpen.value = !isOpen.value;
}

function handleDownload({ withMetadata, event }: { withMetadata: boolean, event: Event }) {
  event.stopPropagation();
  props.onDownload({ withMetadata });
  isOpen.value = false;
}

function handleClickOutside({ event }: { event: MouseEvent }) {
  if (dropdownRef.value && !dropdownRef.value.contains(event.target as Node)) {
    isOpen.value = false;
  }
}

useEventTargetListener(document, 'mousedown', (event) => handleClickOutside({ event }));


defineExpose({
  ...((__BUILD_MODE_IS_TEST__ && {
    TEST_ONLY: {
      // Export internal state and logic used only for testing here. Do not reference these in production logic.
    },
  }) || {}),
});

import "virtual:naidan-tailwind-css-module/75efc929ef97262b3cd2e1832d31532a87024922f3051b35396941cbad5e7095.js";
import "virtual:naidan-tailwind-css-module/e40bc904c786b5e9b6d5d61d2c4dd934a3c92e31e2662ea2701aeab4186f30e5.js";
import "virtual:naidan-tailwind-css-module/ebecc4fd674ef82f183437255486fe38e6831e60d5730478c48be6aabd6a8f8f.js";
</script>

<template>
  <div
    tw-class="relative inline-flex shadow-sm border border-gray-200 dark:border-gray-700 rounded-lg overflow-visible bg-white dark:bg-gray-800 z-30"
    ref="dropdownRef"
  >
    <!-- Main Button (Standard Download) -->
    <button
      @click="handleDownload({ withMetadata: false, event: $event })"
      tw-class="flex items-center justify-center p-1.5 text-gray-500 hover:text-blue-600 dark:hover:text-blue-400 transition-colors rounded-l-lg"
      :title="lazyStrings.ImageDownloadButton__download_image()"
      data-testid="download-gen-image-button"
    >
      <DownloadIcon tw-class="w-4 h-4" />
    </button>

    <!-- Split Divider & Dropdown Toggle -->
    <button
      @click="toggleDropdown({ event: $event })"
      tw-class="px-1 text-gray-500 hover:text-blue-600 dark:hover:text-blue-400 border-l border-gray-200 dark:border-gray-700 transition-colors rounded-r-lg flex items-center justify-center"
      :title="lazyStrings.ImageDownloadButton__more_options()"
      data-testid="download-gen-image-dropdown-toggle"
    >
      <ChevronDownIcon :tw-class="['w-3.5 h-3.5 transition-transform duration-200', { 'rotate-180': isOpen }]" />
    </button>

    <!-- Dropdown Menu -->
    <div
      v-if="isOpen"
      class="animate-in fade-in slide-in-from-top-1"
      :tw-class="['absolute top-full mt-1 w-48 bg-white dark:bg-gray-800 border border-gray-200 dark:border-gray-700 rounded-lg shadow-xl z-[100] py-1 overflow-hidden', align === 'left' ? 'left-0' : 'right-0']"
    >
      <button
        @click="isSupported !== false ? handleDownload({ withMetadata: true, event: $event }) : null"
        :tw-class="['w-full flex flex-col px-3 py-2 text-left transition-colors', isSupported !== false ? 'hover:bg-gray-50 dark:hover:bg-gray-700 text-gray-700 dark:text-gray-200' : 'opacity-50 cursor-not-allowed text-gray-400']"
        :disabled="isSupported === false"
        data-testid="download-with-metadata-option"
      >
        <div tw-class="flex items-center gap-2 mb-0.5">
          <DownloadIcon :tw-class="['w-3.5 h-3.5', isSupported !== false ? 'text-blue-500' : 'text-gray-400']" />
          <span tw-class="font-bold text-xs">{{ lazyStrings.ImageDownloadButton__with_metadata() }}</span>
        </div>
        <span :tw-class="['text-[10px] ml-5', isSupported !== false ? 'text-gray-500 dark:text-gray-400' : 'text-gray-400']">
          {{ isSupported !== false ? lazyStrings.ImageDownloadButton__embed_prompt_seed_etc() : lazyStrings.ImageDownloadButton__not_supported_for_this_format() }}
        </span>
      </button>
    </div>
  </div>
</template>
