<script setup lang="ts">
import { computed, ref, onMounted, nextTick, watch, onUnmounted, provide } from 'vue';
import BlockMarkdownRenderer from './block-markdown/BlockMarkdownRenderer.vue';
import GeneratingIndicator from './GeneratingIndicator.vue';
import { markRaw } from 'vue';
import 'katex/dist/katex.min.css';
import type { MessageNode, Attachment, EndpointType, LmParameters, Reasoning } from '@/01-models/types';
import type { ToolCallDraft } from '@/01-models/lm';
import ToolCallDraftItem from '@/features/tools/components/ToolCallDraftItem.vue';
import type { FlowMetadata, MessageMode } from '@/composables/useChatDisplayFlow';
import { EMPTY_LM_PARAMETERS } from '@/01-models/types';
import { UserIcon, BirdIcon, ChevronLeftIcon, ChevronRightIcon, AlertTriangleIcon, DownloadIcon, RefreshCwIcon, Settings2Icon, XCircleIcon, SquareIcon, FileEditIcon, MoreHorizontalIcon, BrainIcon } from 'lucide-vue-next';
import { storageService } from '@/00-storage/service';
// IMPORTANT: SpeechControl is used in every message and should be immediately available.
import SpeechControl from '@/features/speech/components/SpeechControl.vue';
// IMPORTANT: ImageConjuringLoader is essential for showing image generation progress immediately.
import ImageConjuringLoader from './ImageConjuringLoader.vue';
import ImageIndexBadge from './ImageIndexBadge.vue';
import MessageThinking from './MessageThinking.vue';
import { getMessageText } from '@/01-models/message-text';
import { getAssistantDisplayParts, getDisplayedMessageText } from '@/logic/message-display';
import { useChatMessageError } from '@/composables/chat/useChatMessageError';
import AssistantWaitingIndicator from './AssistantWaitingIndicator.vue';
import MessageActions from './MessageActions.vue';
import SpeechLanguageSelector from '@/features/speech/components/SpeechLanguageSelector.vue';
import { transformersJsService } from '@/features/transformers-js';
import LlamaCppBrowserLoadingIndicator from '@/features/llama-cpp-browser/components/LlamaCppBrowserLoadingIndicator.vue';
import { defineAsyncComponentAndLoadOnMounted } from '@/utils/vue';
import { idToRaw, toBinaryObjectId } from '@/01-models/ids';
import type { AttachmentId, BinaryObjectId, ChatId, MessageId } from '@/01-models/ids';
const ImageGenerationSettings = defineAsyncComponentAndLoadOnMounted({ loader: () => import('./ImageGenerationSettings.vue') });
const ReasoningSettings = defineAsyncComponentAndLoadOnMounted({ loader: () => import('./ReasoningSettings.vue') });
const MessageDiffModal = defineAsyncComponentAndLoadOnMounted({ loader: () => import('./MessageDiffModal.vue') });
const AdvancedTextEditor = defineAsyncComponentAndLoadOnMounted({ loader: () => import('@/features/advanced-text-editor-v3/components/AdvancedTextEditorV3.vue') });
import { useImagePreview, MESSAGE_CONTEXTUAL_PREVIEW_KEY, type BinaryObjectPreviewItem } from '@/composables/useImagePreview';
import { useLayout } from '@/composables/useLayout';
import { lazyStrings } from '@/strings';
import { useSettings } from '@/composables/useSettings';
import { useChatImageProgress } from '@/composables/chat/useChatImageProgress';
import { useChatMetadata } from '@/composables/chat/useChatMetadata';
import {
  isImageGenerationPending,
  isImageGenerationProcessed,
  getImageGenerationProgress,
  stripNaidanSentinels,
  isImageRequest,
  parseImageRequest,
  createImageRequestMarker,
} from '@/utils/image-generation';

const props = withDefaults(defineProps<{
  chatId: ChatId,
  message: MessageNode,
  siblings?: MessageNode[],
  canGenerateImage?: boolean,
  isProcessing?: boolean,
  isGenerating?: boolean,
  isThinkingActive?: boolean,
  availableImageModels?: string[],
  endpointType?: EndpointType,
  flow?: FlowMetadata,
  mode?: MessageMode,
  partContent?: string,
  toolCallDrafts?: readonly ToolCallDraft[],
  isFirstInNode?: boolean,
  isLastInNode?: boolean,
  isFirstInTurn?: boolean,
  showGeneratingIndicator?: boolean,
}>(), {
  flow: () => ({ position: 'standalone', nesting: 'none' }),
  isGenerating: false,
  isThinkingActive: undefined,
  mode: 'content',
  isFirstInNode: true,
  isLastInNode: true,
  isFirstInTurn: false,
  showGeneratingIndicator: false,
});

const emit = defineEmits<{
  (e: 'fork', messageId: MessageId): void,
  (e: 'edit', messageId: MessageId, newContent: string, lmParameters: LmParameters | undefined): void,
  (e: 'switch-version', messageId: MessageId): void,
  (e: 'regenerate', messageId: MessageId): void,
  (e: 'abort'): void,
}>();

const showLlamaCppStatus = computed(() => props.isGenerating && props.showGeneratingIndicator && props.endpointType === 'llama_cpp_browser');

const isEditing = ref(false);
const isAdvancedEditorOpen = ref(false);
const showExtensions = ref(false);
const rawContent = computed(() => getMessageText({ message: props.message }));
const attachments = computed<Attachment[]>(() => props.message.parts.flatMap(part => {
  switch (part.type) {
  case 'attachment': return [part.attachment];
  case 'text':
  case 'reasoning':
  case 'tool_call':
  case 'tool_result': return [];
  default: { const _ex: never = part; throw new Error(`Unhandled message part: ${_ex}`); }
  }
}));
const messageError = useChatMessageError({ chatId: computed(() => props.chatId), message: computed(() => props.message) });
const editContent = ref(rawContent.value);
const textareaRef = ref<HTMLTextAreaElement | null>(null);

const showDiffModal = ref(false);

const transformersStatus = ref(transformersJsService.getState().status);
let transformersUnsubscribe: (() => void) | null = null;

const isImageRequestMsg = computed(() => isImageRequest({ content: rawContent.value }));
const showImageSettings = ref(false);
const editImageMode = ref(false);
const editImageParams = ref({
  width: 512,
  height: 512,
  model: undefined as string | undefined,
  count: 1,
  steps: undefined as number | undefined,
  seed: undefined as number | 'browser_random' | undefined,
  persistAs: 'original' as 'original' | 'webp' | 'jpeg' | 'png',
});

const attachmentUrls = ref(new Map<AttachmentId, string>());
const messageChatId = computed(() => props.chatId);

const { openPreview } = useImagePreview();
const chatMetadata = useChatMetadata();
const chatImageProgress = useChatImageProgress({
  chatId: messageChatId,
});
const chatReasoningEffort = chatMetadata.reasoningEffort({
  chatId: messageChatId,
});
const { preferredEditorMode, setPreferredEditorMode } = useLayout();
const { settings } = useSettings();
const imageProgressCurrentStep = computed(() => chatImageProgress.currentStep.value);
const imageProgressTotalSteps = computed(() => chatImageProgress.totalSteps.value);

const editReasoningEffort = ref<Reasoning['effort']>(undefined);

function openAdvancedEditor() {
  isAdvancedEditorOpen.value = true;
}

function closeAdvancedEditor() {
  isAdvancedEditorOpen.value = false;
}

function handleAdvancedEditorUpdate({ content: newContent }: { content: string }) {
  editContent.value = newContent;
}

function handleAdvancedEditorModeUpdate({ mode }: { mode: 'advanced' | 'textarea' }) {
  setPreferredEditorMode({ mode });
}

let previewRequest = 0;
watch([() => props.chatId, () => props.message], () => {
  previewRequest += 1;
});
onUnmounted(() => {
  previewRequest += 1;
});

async function handlePreviewImage({ id }: { id: BinaryObjectId }) {
  const request = ++previewRequest;
  // Capture local attachment bytes before waiting for generated-image metadata.
  const allImages: BinaryObjectPreviewItem[] = attachments.value
    .filter((attachment): attachment is Exclude<Attachment, { status: 'missing' }> => attachment.status !== 'missing' && attachment.mimeType.startsWith('image/'))
    .map(attachment => ({
      id: attachment.binaryObjectId,
      mimeType: attachment.mimeType,
      size: attachment.size,
      createdAt: attachment.uploadedAt,
      name: attachment.originalName,
      memoryBlob: (() => {
        switch (attachment.status) {
        case 'memory': return attachment.blob;
        case 'persisted': return undefined;
        default: {
          const unhandled: never = attachment;
          throw new Error(`Unhandled attachment: ${unhandled}`);
        }
        }
      })(),
    }));
  const ids = new Set<BinaryObjectId>([id]);
  for (const element of messageRef.value?.querySelectorAll<HTMLElement>('.naidan-generated-image') ?? []) {
    if (element.dataset.id) ids.add(toBinaryObjectId({ raw: element.dataset.id }));
  }
  for (const binaryObjectId of ids) {
    if (allImages.some(image => image.id === binaryObjectId)) continue;
    const object = await storageService.getBinaryObject({ binaryObjectId });
    if (request !== previewRequest) return;
    if (object?.mimeType.startsWith('image/')) allImages.push({ ...object, memoryBlob: undefined });
  }
  if (request !== previewRequest || !allImages.some(image => image.id === id)) return;
  openPreview({ objects: allImages, initialId: id });
}

provide(MESSAGE_CONTEXTUAL_PREVIEW_KEY, handlePreviewImage);

async function loadAttachments() {
  for (const att of attachments.value) {
    switch (att.status) {
    case 'memory':
      attachmentUrls.value.set(att.id, URL.createObjectURL(att.blob));
      break;
    case 'persisted':
      try {
        const blob = await storageService.getFile({ binaryObjectId: att.binaryObjectId });
        if (blob) {
          attachmentUrls.value.set(att.id, URL.createObjectURL(blob));
        }
      } catch (e) {
        console.error('Failed to load persisted attachment:', e);
      }
      break;
    case 'missing':
      break;
    default: {
      const _ex: never = att;
      throw new Error(`Unhandled attachment status: ${_ex}`);
    }
    }
  }
}

const isMac = (() => {
  const t = typeof window;
  switch (t) {
  case 'undefined': return false;
  case 'object':
  case 'boolean':
  case 'string':
  case 'number':
  case 'function':
  case 'symbol':
  case 'bigint':
    return /Mac|iPod|iPhone|iPad/.test(navigator.platform);
  default: {
    const _ex: never = t;
    return _ex;
  }
  }
})();
const sendShortcutText = isMac ? 'Cmd + Enter' : 'Ctrl + Enter';

// Focus and move cursor to end when editing starts
watch(isEditing, (editing) => {
  if (editing) {
    editContent.value = stripNaidanSentinels({ content: rawContent.value });

    // Initialize reasoning effort from message if available, otherwise from current chat
    if (props.message.role === 'user' && props.message.lmParameters?.reasoning) {
      editReasoningEffort.value = props.message.lmParameters.reasoning.effort;
    } else {
      editReasoningEffort.value = chatReasoningEffort.value;
    }

    // Initialize image generation settings if it's an image request
    if (isImageRequestMsg.value) {
      editImageMode.value = true;
      const parsed = parseImageRequest({ content: rawContent.value });
      if (parsed) {
        editImageParams.value = {
          width: parsed.width ?? 512,
          height: parsed.height ?? 512,
          model: parsed.model || undefined,
          count: parsed.count ?? 1,
          steps: parsed.steps,
          seed: parsed.seed,
          persistAs: parsed.persistAs ?? 'original',
        };
      }
    } else {
      editImageMode.value = false;
    }

    // Auto-open tools if either image mode or non-default reasoning is active
    showImageSettings.value = editImageMode.value || editReasoningEffort.value !== undefined;

    nextTick(() => {
      if (textareaRef.value) {
        textareaRef.value.focus();
        // Move cursor to end
        textareaRef.value.selectionStart = textareaRef.value.value.length;
        textareaRef.value.selectionEnd = textareaRef.value.value.length;
      }
    });
  }
});

const versionInfo = computed(() => {
  if (!props.siblings || props.siblings.length <= 1) return null;
  const index = props.siblings.findIndex(m => m.id === props.message.id);
  return {
    current: index + 1,
    total: props.siblings.length,
    hasPrev: index > 0,
    hasNext: index < props.siblings.length - 1,
    prevId: index > 0 ? props.siblings[index - 1]?.id : null,
    nextId: index < props.siblings.length - 1 ? props.siblings[index + 1]?.id : null,
  };
});

function handleSaveEdit() {
  if (editContent.value.trim()) {
    let finalContent = editContent.value;
    if (editImageMode.value) {
      const marker = createImageRequestMarker({
        width: editImageParams.value.width,
        height: editImageParams.value.height,
        model: editImageParams.value.model,
        count: editImageParams.value.count,
        steps: editImageParams.value.steps,
        seed: editImageParams.value.seed,
        persistAs: editImageParams.value.persistAs,
      });
      finalContent = marker + '\n' + finalContent;
    }
    const lmParameters: LmParameters = {
      ...(settings.value.lmParameters || EMPTY_LM_PARAMETERS),
      stop: settings.value.lmParameters?.stop ? [...settings.value.lmParameters.stop] : undefined,
      reasoning: { effort: editReasoningEffort.value },
    };
    emit('edit', props.message.id, finalContent, lmParameters);
  }
  isEditing.value = false;
}

function handleCancelEdit() {
  editContent.value = stripNaidanSentinels({ content: rawContent.value });
  isEditing.value = false;
}

function handleClearContent() {
  editContent.value = '';
  nextTick(() => {
    textareaRef.value?.focus();
  });
}

onMounted(() => {
  loadAttachments();

  transformersUnsubscribe = transformersJsService.subscribe({
    listener: ({ status: s }) => {
      transformersStatus.value = s;
    },
  });

});

onUnmounted(() => {
  attachmentUrls.value.forEach(url => URL.revokeObjectURL(url));

  if (transformersUnsubscribe) transformersUnsubscribe();
});

const messageRef = ref<HTMLElement | null>(null);

const displayContent = computed(() => {
  const mode = props.mode;
  switch (mode) {
  case 'content': {
    if (props.partContent !== undefined) return props.partContent;
    return getDisplayedMessageText({ message: props.message });
  }
  case 'thinking':
  case 'waiting':
  case 'tool_calls':
    return '';
  default: {
    const _ex: never = mode;
    return _ex;
  }
  }
});

const isImageResponse = computed(() => isImageGenerationProcessed({ content: rawContent.value }));

const speechText = computed(() => {
  const mode = props.mode;
  switch (mode) {
  case 'content': {
    const text = props.partContent !== undefined ? props.partContent : displayContent.value;
    if (!text) return '';
    if (isImageResponse.value) return lazyStrings.MessageItem__image_generated();
    return text.replace(/<[^>]*>/g, '');
  }
  case 'thinking':
  case 'waiting':
  case 'tool_calls':
    return '';
  default: {
    const _ex: never = mode;
    return _ex;
  }
  }
});

const isUser = computed((): boolean => {
  const node = props.message;
  switch (node.role) {
  case 'user': return true;
  case 'assistant':
  case 'system':
  case 'tool':
    return false;
  default: {
    const _ex: never = node;
    return (_ex as { role: string }).role === 'user';
  }
  }
});

const reasoningEffortLabel = computed(() => {
  const effort = (() => {
    switch (props.message.role) {
    case 'assistant':
      return props.message.lmParameters?.reasoning?.effort;
    case 'user':
    case 'system':
    case 'tool':
      return undefined;
    default: {
      const _ex: never = props.message;
      throw new Error(`Unhandled role: ${(_ex as { role: string }).role}`);
    }
    }
  })();

  if (effort === undefined) return undefined;

  switch (effort) {
  case 'none':
    return lazyStrings.MessageItem__off();
  case 'low':
  case 'medium':
  case 'high':
    return lazyStrings.MessageItem__think();
  default: {
    const _ex: never = effort;
    return _ex;
  }
  }
});

const reasoningEffortTooltip = computed(() => {
  const effort = (() => {
    switch (props.message.role) {
    case 'assistant':
      return props.message.lmParameters?.reasoning?.effort;
    case 'user':
    case 'system':
    case 'tool':
      return undefined;
    default: {
      const _ex: never = props.message;
      throw new Error(`Unhandled role: ${(_ex as { role: string }).role}`);
    }
    }
  })();

  if (effort === undefined) return undefined;

  switch (effort) {
  case 'none':
    return lazyStrings.MessageItem__think_disabled();
  case 'low':
  case 'medium':
  case 'high': {
    const effortLabel = (() => {
      switch (effort) {
      case 'low':
        return lazyStrings.MessageItem__low();
      case 'medium':
        return lazyStrings.MessageItem__medium();
      case 'high':
        return lazyStrings.MessageItem__high();
      default: {
        const _ex: never = effort;
        return _ex;
      }
      }
    })();
    if (effortLabel === undefined) return undefined;
    return lazyStrings.MessageItem__think_effort_note({ effortLabel });
  }
  default: {
    const _ex: never = effort;
    return _ex;
  }
  }
});

const hasThinking = computed(() => props.message.role === 'assistant' && getAssistantDisplayParts({ message: props.message }).some(part => part.type === 'reasoning'));

const thinkingIsActive = computed(() => props.isThinkingActive ?? (props.isGenerating && !messageError.value && props.message.role === 'assistant' && props.message.interruption === undefined && getAssistantDisplayParts({ message: props.message }).some(part => part.type === 'reasoning' && part.completeness === 'partial')));

function formatSize({ bytes }: { bytes: number | undefined }): string {
  if (bytes === undefined) return '0 B';
  const units = ['B', 'KB', 'MB', 'GB'];
  let size = bytes;
  let unitIndex = 0;
  while (size >= 1024 && unitIndex < units.length - 1) {
    size /= 1024;
    unitIndex++;
  }
  return `${size.toFixed(1)} ${units[unitIndex]}`;
}

const showHeader = computed(() => props.flow.position === 'standalone' || props.flow.position === 'start');
const isNested = computed(() => props.flow.nesting === 'inside-group');

defineExpose({
  ...((__BUILD_MODE_IS_TEST__ && {
    TEST_ONLY: {
      openAdvancedEditor,
      handleAdvancedEditorModeUpdate,
    },
  }) || {}),
});

import "virtual:naidan-tailwind-css-module/0eea1ccb759d376dc6850e80ccb4026870cc6636a2829841cbd780378d3f79e4.js";
import "virtual:naidan-tailwind-css-module/329970ea468b3129ae49c0fe88556982cfa5549acf4bec685b3588d2f1427b09.js";
import "virtual:naidan-tailwind-css-module/5b33de7a23d23ffe375bebbfe2be35862d78e938df7f7a30f4a28f6e08f496fb.js";
import "virtual:naidan-tailwind-css-module/63dcd5d5283129e5fa0f51b7e4e92df326806d3caa3b006097625ff142db8cff.js";
import "virtual:naidan-tailwind-css-module/6a9b2411bff60b47c9f330af20993a5ca2e84d586d74ca0c64772066f6529eba.js";
import "virtual:naidan-tailwind-css-module/7a02098952c2c3c2f9bd61c2d4167d7f3ab0703e1f9686e6a887ceb415314a68.js";
import "virtual:naidan-tailwind-css-module/9b55c9c2041a7178c87de6025f85124e29799512ad0b3520824b32bceb8160a7.js";
import "virtual:naidan-tailwind-css-module/b521e235b4efb22b5e330a04e4d91f8c39b2c049a3cdff309119a66c11397e7d.js";
import "virtual:naidan-tailwind-css-module/bc24bbe30a826281be036c85ad7dd1b066205fe01b2fb62461677efe66ec9344.js";
import "virtual:naidan-tailwind-css-module/bd5518240d103fdc790d66490d27072253d242a50b0873716ccac17cc344fd2b.js";
import "virtual:naidan-tailwind-css-module/d07c087eede766ef60c7f9acf5436efdaa22c157dab5f92ae4b964c56e73dbab.js";
