<script setup lang="ts">
import { lazyStrings } from '@/strings';
import { computed, ref, watch, nextTick, inject } from 'vue';
import type { Component } from 'vue';
import { BrainIcon } from 'lucide-vue-next';
import { getAssistantDisplayParts } from '@/logic/message-display';
import type { MessageNode } from '@/01-models/types';

const props = defineProps<{
  message: MessageNode,
  noMargin?: boolean,
  partContent?: string,
  isActive?: boolean,
  trailingInline?: Component,
}>();

type ThinkingMode = 'expanded' | 'collapsed-active' | 'collapsed-finished';

const inSequence = inject<boolean>('inSequence', false);

const isUserExpanded = ref(false);
const thinkingContentRef = ref<HTMLElement | null>(null);
const previewRef = ref<HTMLElement | null>(null);
const isPreviewOverflowing = ref(false);

const reasoningParts = computed(() => {
  const message = props.message;
  switch (message.role) {
  case 'assistant': return getAssistantDisplayParts({ message }).filter(part => part.type === 'reasoning');
  case 'user':
  case 'system':
  case 'tool': return [];
  default: { const _ex: never = message; throw new Error(`Unhandled message: ${_ex}`); }
  }
});
const displayThinking = computed(() => props.partContent !== undefined
  ? props.partContent
  : reasoningParts.value.map(part => part.text).join('\n\n---\n\n'));
const hasThinking = computed(() => props.partContent !== undefined || reasoningParts.value.length > 0);
// A persisted partial is not by itself evidence of an active model request.
const isThinkingNow = computed(() => props.isActive === true);

const mode = computed<ThinkingMode>(() => {
  if (isUserExpanded.value) return 'expanded';
  return isThinkingNow.value ? 'collapsed-active' : 'collapsed-finished';
});

function handleToggleThinking() {
  if (typeof window !== 'undefined' && window.getSelection()?.toString()) return;
  isUserExpanded.value = !isUserExpanded.value;
}

// Auto-scroll to bottom during active thinking
watch(displayThinking, async () => {
  const currentMode = mode.value;
  switch (currentMode) {
  case 'collapsed-active':
    await nextTick();
    if (thinkingContentRef.value) {
      thinkingContentRef.value.scrollTop = thinkingContentRef.value.scrollHeight;
    }
    break;
  case 'expanded':
  case 'collapsed-finished':
    break;
  default: {
    const _ex: never = currentMode;
    return _ex;
  }
  }
});

watch([displayThinking, mode], async ([, newMode]) => {
  if (inSequence && newMode === 'collapsed-finished') {
    await nextTick();
    if (previewRef.value) {
      isPreviewOverflowing.value = previewRef.value.scrollHeight > previewRef.value.clientHeight;
    }
  } else {
    isPreviewOverflowing.value = false;
  }
}, { immediate: true });

defineExpose({
  ...((__BUILD_MODE_IS_TEST__ && {
    TEST_ONLY: {
      isUserExpanded,
      mode,
      handleToggleThinking,
    },
  }) || {}),
});

import "virtual:naidan-tailwind-css-module/1467faa67f2e1854474547fd2dad2da1c52018e938e15e1166528fb49bfec94f.js";
import "virtual:naidan-tailwind-css-module/14c0c0ba32aa3c3b79f85a61ae6f108f23b2d0c65046131dcb6b1d430753b880.js";
import "virtual:naidan-tailwind-css-module/26ff1a8bd158f235cc96f218da813d5325a0b914d52aef990e96b104e72dc0a1.js";
import "virtual:naidan-tailwind-css-module/942f36d832bedce92c49696bf7ad4d374cf79d11e88ce3f6ddc9d0eac79984d5.js";
import "virtual:naidan-tailwind-css-module/bc52073a8fbbdd5ce14ae456914da0023cc8561fa18f9feb9407e0dee986813a.js";
import "virtual:naidan-tailwind-css-module/e40bc904c786b5e9b6d5d61d2c4dd934a3c92e31e2662ea2701aeab4186f30e5.js";
import "virtual:naidan-tailwind-css-module/ebecc4fd674ef82f183437255486fe38e6831e60d5730478c48be6aabd6a8f8f.js";
</script>

<template>
  <div v-if="hasThinking" :tw-class="['isolate', noMargin ? '' : 'mb-3']" data-testid="thinking-block">
    <div
      :tw-class="['transition-all duration-500 ease-in-out relative group/thinking w-full',
                  /* Shape & Size */
                  mode === 'expanded' ? 'p-5 rounded-2xl min-h-[100px]' : '',
                  mode === 'collapsed-active' ? 'p-4 rounded-xl h-32 overflow-hidden' : '',
                  mode === 'collapsed-finished' ? 'px-3 py-1.5 rounded-xl' : '',

                  'cursor-pointer',

                  /* State: Active Thinking */
                  isThinkingNow
                    ? 'overflow-visible'
                    : 'border shadow-sm overflow-hidden',

                  /* Background & Colors */
                  mode === 'expanded' || mode === 'collapsed-active'
                    ? 'bg-gradient-to-br from-blue-50/50 to-sky-50/50 dark:from-blue-950/20 dark:to-sky-950/20 border-blue-100/50 dark:border-blue-800/30 shadow-inner'
                    : 'bg-white dark:bg-gray-800/50 border-blue-100/50 dark:border-blue-800/30 hover:border-blue-200 dark:hover:border-blue-800'
      ]"
      @click="handleToggleThinking"
      data-testid="toggle-thinking"
    >
      <!-- Dedicated Thinking Border Element (Only when active) -->
      <div
        v-if="isThinkingNow"
        class="thinking-gradient-border" tw-class="absolute inset-0 pointer-events-none"
        style="border-radius: inherit;"
      ></div>

      <!-- Header / Button Content -->
      <div
        data-testid="thinking-header"
        :tw-class="['flex items-center gap-2 text-[10px] font-bold tracking-wider relative z-20 transition-colors',
                    mode === 'expanded' || mode === 'collapsed-active' ? 'mb-2 text-blue-600 dark:text-blue-400' : 'text-gray-500 dark:text-gray-400 group-hover/thinking:text-blue-600',
                    isThinkingNow ? 'animate-pulse text-blue-700 dark:text-blue-400' : ''
        ]"
      >
        <BrainIcon tw-class="w-3.5 h-3.5" />
        <span v-if="isThinkingNow">{{ lazyStrings.MessageThinking__thinking() }}</span>
        <span v-else-if="mode === 'expanded'">{{ lazyStrings.MessageThinking__hide_thought_process() }}</span>
        <span v-else-if="inSequence">{{ lazyStrings.MessageThinking__thought_process() }}</span>
        <span v-else>{{ lazyStrings.MessageThinking__show_thought_process() }}</span>
      </div>

      <!-- In-sequence preview: height-limited content for collapsed-finished -->
      <div
        v-if="inSequence && mode === 'collapsed-finished' && displayThinking"
        ref="previewRef"
        tw-class="relative max-h-32 overflow-hidden mt-1 text-gray-600 dark:text-gray-400 text-[11px] font-mono whitespace-pre-wrap leading-relaxed"
        data-testid="thinking-preview"
      >
        {{ displayThinking }}
        <div
          v-if="isPreviewOverflowing"
          tw-class="absolute bottom-0 left-0 right-0 h-10 bg-gradient-to-t from-white dark:from-gray-800 to-transparent cursor-pointer"
          data-testid="thinking-preview-expand"
          @click.stop="handleToggleThinking"
        />
      </div>

      <!-- Content Container -->
      <div
        ref="thinkingContentRef"
        v-if="mode === 'expanded' || mode === 'collapsed-active'"
        class="animate-in fade-in slide-in-from-top-1"
        :class="[mode === 'collapsed-active' ? 'no-scrollbar mask-fade-top' : '']"
        :tw-class="[
          'relative z-20 text-gray-600 dark:text-gray-400 text-[11px] font-mono whitespace-pre-wrap leading-relaxed duration-200 scroll-smooth',
          mode === 'collapsed-active' ? 'h-20 overflow-y-auto pt-2' : ''
        ]"
        data-testid="thinking-content"
      >
        <!-- Brain watermark -->
        <div tw-class="absolute top-0 right-0 opacity-[0.03] dark:opacity-[0.07] pointer-events-none -mt-4">
          <BrainIcon tw-class="w-16 h-16" />
        </div>

        <div tw-class="flex flex-col min-h-full">
          <span>{{ displayThinking.trimEnd() }}<component :is="trailingInline" v-if="trailingInline" /></span>
        </div>
      </div>
    </div>
    <!-- Indicator shown after collapsed-finished pill while still generating -->
    <component :is="trailingInline" v-if="trailingInline && mode === 'collapsed-finished'" tw-class="ml-1" />
  </div>
</template>

<style scoped>
@property --thinking-angle {
  syntax: '<angle>';
  initial-value: 0deg;
  inherits: false;
}

@keyframes thinking-sweep {
  0% {
    --thinking-angle: 0deg;
    opacity: 0;
  }
  2% {
    opacity: 1;
  }
  35% {
    --thinking-angle: 360deg;
    opacity: 1;
  }
  40% {
    opacity: 0;
  }
  100% {
    --thinking-angle: 360deg;
    opacity: 0;
  }
}

.thinking-gradient-border {
  padding: 1.2px;
  box-shadow: 0 0 20px -5px rgba(59, 130, 246, 0.4);
  background: conic-gradient(
    from var(--thinking-angle),
    #3b82f6 0%,
    #8b5cf6 10%,
    #06b6d4 20%,
    transparent 40%,
    transparent 100%
  );
  -webkit-mask:
    linear-gradient(#fff 0 0) content-box,
    linear-gradient(#fff 0 0);
  -webkit-mask-composite: xor;
  mask:
    linear-gradient(#fff 0 0) content-box,
    linear-gradient(#fff 0 0);
  mask-composite: exclude;
  animation: thinking-sweep 0.9s linear infinite;
  z-index: 10;
}

/* Fades the top of the content in collapsed-active mode to emphasize "newest at bottom" */
.mask-fade-top {
  mask-image: linear-gradient(to bottom, transparent 0px, black 16px);
  -webkit-mask-image: linear-gradient(to bottom, transparent 0px, black 16px);
}

.no-scrollbar::-webkit-scrollbar {
  display: none;
}
.no-scrollbar {
  -ms-overflow-style: none;
  scrollbar-width: none;
}
</style>
