<script setup lang="ts">
import { ensureStrings, lazyStrings } from '@/strings';
import { ref, computed, onMounted, onUnmounted, watch, inject } from 'vue';
import { GeneratedImageBlockSchema, getDisplayDimensions } from '@/utils/image-generation';
import { storageService } from '@/00-storage/service';
import { ImageIcon, AlertTriangleIcon } from 'lucide-vue-next';
import ImageDownloadButton from '@/components/ImageDownloadButton.vue';
import ImageInfoDisplay from '@/components/ImageInfoDisplay.vue';
import { ImageDownloadHydrator } from '@/components/ImageDownloadHydrator';
import { useImagePreview, MESSAGE_CONTEXTUAL_PREVIEW_KEY } from '@/composables/useImagePreview';
import { useGlobalEvents } from '@/composables/useGlobalEvents';
import { toBinaryObjectId } from '@/01-models/ids';

const props = defineProps<{
  json: string,
}>();

const parsed = computed(() => {
  try {
    const data = JSON.parse(props.json);
    const result = GeneratedImageBlockSchema.safeParse(data);
    if (result.success) return result.data;
    console.error('Invalid generated image block:', result.error);
    return undefined;
  } catch (e) {
    console.error('Failed to parse generated image JSON:', e);
    return undefined;
  }
});

const imageUrl = ref<string | undefined>(undefined);
const loading = ref(true);
const error = ref<string | undefined>(undefined);
const isSupported = ref(false);

const { openPreview } = useImagePreview();
const handleContextualPreview = inject(MESSAGE_CONTEXTUAL_PREVIEW_KEY, null);
const { addErrorEvent } = useGlobalEvents();

const displayDims = computed(() => {
  if (!parsed.value) return { width: 300, height: 300 };
  return getDisplayDimensions({
    width: parsed.value.width,
    height: parsed.value.height,
    displayWidth: parsed.value.displayWidth,
    displayHeight: parsed.value.displayHeight,
  });
});

async function loadImage() {
  if (!parsed.value) return;

  loading.value = true;
  error.value = undefined;

  try {
    const blob = await storageService.getFile({ binaryObjectId: toBinaryObjectId({ raw: parsed.value.binaryObjectId }) });
    if (blob) {
      if (imageUrl.value) URL.revokeObjectURL(imageUrl.value);
      imageUrl.value = URL.createObjectURL(blob);
      isSupported.value = await ImageDownloadHydrator.detectSupport({ blob });
    } else {
      error.value = await ensureStrings.blockMarkdown__image_not_found_in_storage();
    }
  } catch (e) {
    error.value = await ensureStrings.blockMarkdown__failed_to_load_image();
    console.error(e);
  } finally {
    loading.value = false;
  }
}

onMounted(loadImage);
watch(() => props.json, loadImage);

onUnmounted(() => {
  if (imageUrl.value) URL.revokeObjectURL(imageUrl.value);
});

async function handlePreview() {
  if (!parsed.value) return;

  if (handleContextualPreview) {
    await handleContextualPreview({ id: toBinaryObjectId({ raw: parsed.value.binaryObjectId }) });
    return;
  }

  const obj = await storageService.getBinaryObject({ binaryObjectId: toBinaryObjectId({ raw: parsed.value.binaryObjectId }) });
  if (obj) {
    openPreview({
      objects: [{ ...obj, memoryBlob: undefined }],
      initialId: toBinaryObjectId({ raw: parsed.value.binaryObjectId }),
    });
  }
}

async function handleDownload({ withMetadata }: { withMetadata: boolean }) {
  if (!parsed.value) return;

  const downloadOptions = {
    id: toBinaryObjectId({ raw: parsed.value.binaryObjectId }),
    name: undefined,
    memoryBlob: undefined,
    prompt: parsed.value.prompt || '',
    steps: parsed.value.steps,
    seed: parsed.value.seed,
    model: undefined, // Model info not directly available in the block JSON currently
    storageService,
  };

  if (withMetadata) {
    const metadataErrorMessage = await ensureStrings.blockMarkdown__failed_to_embed_metadata_in_image();
    await ImageDownloadHydrator.download({
      ...downloadOptions,
      withMetadata: true,
      onError: ({ error }) => addErrorEvent({
        source: 'GeneratedImageBlock:Download',
        message: metadataErrorMessage,
        details: error instanceof Error ? error.message : String(error),
      }),
    });
    return;
  }

  await ImageDownloadHydrator.download({
    ...downloadOptions,
    withMetadata: false,
    onError: () => {},
  });
}

defineExpose({
  ...((__BUILD_MODE_IS_TEST__ && {
    TEST_ONLY: {
      // Export internal state and logic used only for testing here. Do not reference these in production logic.
    },
  }) || {}),
});

import "virtual:naidan-tailwind-css-module/0eea1ccb759d376dc6850e80ccb4026870cc6636a2829841cbd780378d3f79e4.js";
import "virtual:naidan-tailwind-css-module/bd5518240d103fdc790d66490d27072253d242a50b0873716ccac17cc344fd2b.js";
</script>

<template>
  <div
    v-if="parsed"
    class="naidan-generated-image" tw-class="my-4 relative group/gen-img w-fit rounded-xl overflow-visible"
    :data-id="parsed.binaryObjectId"
  >
    <!-- Image -->
    <img
      v-if="imageUrl"
      :src="imageUrl"
      @click="handlePreview"
      :width="displayDims.width"
      :height="displayDims.height"
      class="naidan-clickable-img" tw-class="rounded-xl shadow-lg border border-gray-100 dark:border-gray-800 max-w-full h-auto !m-0 block cursor-pointer hover:opacity-95 transition-opacity"
      :alt="lazyStrings.SHARED__generated_image()"
    />

    <!-- Loading Skeleton -->
    <div
      v-else-if="loading"
      class="naidan-image-skeleton" tw-class="flex items-center justify-center bg-gray-100 dark:bg-gray-800 animate-pulse !m-0 rounded-xl"
      :style="{ width: `${displayDims.width}px`, maxWidth: '100%', aspectRatio: `${displayDims.width} / ${displayDims.height}` }"
    >
      <ImageIcon tw-class="w-8 h-8 text-gray-400" />
    </div>

    <!-- Error -->
    <div
      v-else-if="error"
      tw-class="p-3 bg-red-50 dark:bg-red-900/20 border border-red-100 dark:border-red-800 rounded-xl text-red-600 dark:text-red-400 text-xs flex flex-col items-center justify-center"
      :style="{ width: `${displayDims.width}px`, maxWidth: '100%', aspectRatio: `${displayDims.width} / ${displayDims.height}` }"
    >
      <AlertTriangleIcon tw-class="w-6 h-6 mb-2" />
      <span>{{ error }}</span>
    </div>

    <!-- Overlays (only if loaded) -->
    <template v-if="imageUrl">
      <!-- Info Badge (Top Left) -->
      <div class="touch-visible" tw-class="absolute top-2 left-2 z-30 opacity-0 group-hover/gen-img:opacity-100 transition-all overflow-visible">
        <ImageInfoDisplay
          :prompt="parsed.prompt || ''"
          :steps="parsed.steps"
          :seed="parsed.seed"
          :width="parsed.width"
          :height="parsed.height"
          align="left"
        />
      </div>

      <!-- Download Button (Top Right) -->
      <div class="touch-visible" tw-class="absolute top-2 right-2 z-30 opacity-0 group-hover/gen-img:opacity-100 transition-all overflow-visible">
        <ImageDownloadButton
          :is-supported="isSupported"
          align="right"
          @download="handleDownload"
        />
      </div>
    </template>
  </div>

  <!-- Fallback for invalid JSON -->
  <div v-else tw-class="p-4 border border-red-200 bg-red-50 rounded text-red-500 text-xs">
    {{ lazyStrings.blockMarkdown__invalid_image_block_data() }}
  </div>
</template>
