<script setup lang="ts">
import { lazyStrings } from '@/strings';
import { computed, watch } from 'vue';
import { Volume2Icon, PauseIcon, SquareIcon, RotateCcwIcon } from 'lucide-vue-next';
import { webSpeechService } from '@/features/speech/logic/web-speech';
import type { MessageId } from '@/01-models/ids';
import { isImageGenerationPending, isImageGenerationProcessed } from '@/utils/image-generation';

const props = defineProps<{
  messageId: MessageId,
  content: string,
  isGenerating?: boolean,
  showFullControls?: boolean,
}>();

const isSupported = webSpeechService.isSupported();
const isThisMessageActive = computed(() => webSpeechService.state.activeMessageId === props.messageId);
const isPlaying = computed(() => isThisMessageActive.value && (webSpeechService.state.status === 'playing' || webSpeechService.state.status === 'waiting'));
const isPaused = computed(() => isThisMessageActive.value && webSpeechService.state.status === 'paused');
const isSpeechActive = computed(() => isThisMessageActive.value && webSpeechService.state.status !== 'inactive');

const isHidden = computed(() => {
  return isImageGenerationProcessed({ content: props.content }) || isImageGenerationPending({ content: props.content });
});

function handleToggleSpeech() {
  if (isPlaying.value && webSpeechService.state.status !== 'waiting') {
    webSpeechService.pause();
  } else {
    webSpeechService.speak({
      text: props.content,
      messageId: props.messageId,
      isFinal: !props.isGenerating,
      lang: webSpeechService.state.preferredLang,
    });
  }
}

function handleStopSpeech() {
  webSpeechService.stop();
}

function handleRestartSpeech() {
  webSpeechService.speak({
    text: props.content,
    messageId: props.messageId,
    isFinal: !props.isGenerating,
    lang: webSpeechService.state.preferredLang,
  });
}

// Watch for global language changes to restart if currently playing
watch(() => webSpeechService.state.preferredLang, () => {
  if (isSpeechActive.value) {
    handleRestartSpeech();
  }
});

// Watch for content updates during streaming
watch(() => props.content, (newContent) => {
  // Direct state check to be absolutely sure
  const state = webSpeechService.state;
  const isCurrentlyPlaying = state.status === 'playing' || state.status === 'waiting';
  const isThisActive = state.activeMessageId === props.messageId;

  if (isCurrentlyPlaying && isThisActive) {
    webSpeechService.speak({
      text: newContent,
      messageId: props.messageId,
      isFinal: false,
      lang: state.preferredLang,
    });
  }
}, { immediate: false });

// Watch for generation completion to flush remaining text
watch(() => props.isGenerating, (isGenerating) => {
  const state = webSpeechService.state;
  const isCurrentlyPlaying = state.status === 'playing' || state.status === 'waiting';
  const isThisActive = state.activeMessageId === props.messageId;

  if (!isGenerating && isCurrentlyPlaying && isThisActive) {
    webSpeechService.speak({
      text: props.content,
      messageId: props.messageId,
      isFinal: true,
      lang: state.preferredLang,
    });
  }
}, { immediate: false });


defineExpose({
  ...((__BUILD_MODE_IS_TEST__ && {
    TEST_ONLY: {
      // Export internal state and logic used only for testing here. Do not reference these in production logic.
    },
  }) || {}),
});

import "virtual:naidan-tailwind-css-module/51181919fa1675bb8802159c4679eb41a0063032306b7da1ccf2e7535a098868.js";
import "virtual:naidan-tailwind-css-module/6f506a4c0f543a091de5b53b381e587a6ba1c3c266800941cf9d0348e2f5ed30.js";
import "virtual:naidan-tailwind-css-module/7ad3864e0bff6deba05aeb87ce694c2c148b15ebb5592c6a2a4ebf8c7910bb56.js";
import "virtual:naidan-tailwind-css-module/89098286b80c7ba90ca103ee32baf549921b6ed8d4dae17c484489d875204562.js";
import "virtual:naidan-tailwind-css-module/ebecc4fd674ef82f183437255486fe38e6831e60d5730478c48be6aabd6a8f8f.js";
</script>

<template>
  <div v-if="isSupported && !isHidden" tw-class="flex items-center gap-0.5">
    <!-- Mini View (Header) -->
    <template v-if="!isSpeechActive || !showFullControls">
      <button
        @click.stop="handleToggleSpeech"
        tw-class="p-1 rounded-lg text-gray-400 hover:text-blue-600 dark:hover:text-blue-400 hover:bg-gray-100/50 dark:hover:bg-gray-800/50 transition-colors"
        :title="isPaused ? lazyStrings.SpeechControl__resume() : lazyStrings.SpeechControl__read_aloud()"
        data-testid="speech-toggle-mini"
      >

        <PauseIcon v-if="isPlaying" tw-class="w-3.5 h-3.5" />
        <Volume2Icon v-else tw-class="w-3.5 h-3.5" />
      </button>
    </template>

    <!-- Full View (Footer) -->
    <template v-else>
      <button @click="handleRestartSpeech" tw-class="p-1.5 text-blue-600/60 dark:text-blue-400/60 hover:text-blue-600 dark:hover:text-blue-400 rounded-md" :title="lazyStrings.SpeechControl__restart()"><RotateCcwIcon tw-class="w-3.5 h-3.5" /></button>
      <button @click="handleStopSpeech" tw-class="p-1.5 text-blue-600/60 dark:text-blue-400/60 hover:text-red-500 dark:hover:text-red-400 rounded-md" :title="lazyStrings.SpeechControl__stop()"><SquareIcon tw-class="w-3.5 h-3.5" /></button>
      <button @click="handleToggleSpeech" tw-class="p-1.5 rounded-md transition-colors text-blue-600 dark:text-blue-400 hover:bg-blue-100/50 dark:hover:bg-blue-800/50" :title="isPaused ? lazyStrings.SpeechControl__resume() : lazyStrings.SpeechControl__pause()">
        <PauseIcon v-if="isPlaying && webSpeechService.state.status !== 'waiting'" tw-class="w-4 h-4" />
        <Volume2Icon v-else tw-class="w-4 h-4" />
      </button>
    </template>
  </div>
</template>
